package com.projectseele.world;
import com.google.gson.*;
import java.util.*;
import net.minecraft.world.phys.Vec3;

/** Synthetic explicit graph tests; these coordinates are never installation data. */
public final class NervAirTransportManifestR52Test
{
    private static int checks;
    private static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
    private static void rejects(Runnable r,String m){boolean caught=false;try{r.run();}catch(RuntimeException invalid){caught=true;}check(caught,m);}
    private static JsonArray numbers(double... values){var a=new JsonArray();for(double n:values)a.add(n);return a;}
    private static JsonArray ids(String... ids){var a=new JsonArray();for(String n:ids)a.add(n);return a;}
    private static JsonObject rigid(double x,double y,double z){var r=new JsonObject();r.add("translation",numbers(x,y,z));r.add("quaternion_xyzw",numbers(0,0,0,1));return r;}
    private static JsonArray cells(int x,int y,int z){var row=new JsonObject();row.add("position",numbers(x,y,z));row.addProperty("state","minecraft:stone");var a=new JsonArray();a.add(row);return a;}
    private static void node(JsonObject root,String id,String region,double x,double y,boolean cargo,String space)
    {var n=new JsonObject();n.addProperty("id",id);n.addProperty("region",region);n.add("occupancy",ids(space));n.add("actual_cells",new JsonArray());var f=new JsonObject();f.add("plane",rigid(x,y,0));if(cargo)f.add("cargo",rigid(x,y-112,0));var rig=new JsonObject();rig.addProperty("hoist",112);rig.addProperty("deployment",cargo?1:0);rig.addProperty("jaws",cargo?0:1);f.add("rig",rig);n.add("frame",f);root.getAsJsonArray("nodes").add(n);}
    private static void corridor(JsonObject root,String id,String a,String b,String reverse,String space)
    {var c=new JsonObject();c.addProperty("id",id);c.addProperty("from",a);c.addProperty("to",b);c.addProperty("ticks",10);if(!reverse.isEmpty())c.addProperty("reverse_of",reverse);c.add("occupancy",ids(space));c.add("gates",new JsonArray());root.getAsJsonArray("corridors").add(c);}
    private static JsonObject fixture(NervRouteDirectoryR52 d)
    {
        var r=new JsonObject();r.addProperty("schema",NervAirTransportManifestR52.SCHEMA);r.addProperty("map_author","root");r.addProperty("status","design");r.addProperty("epoch",d.epoch());r.addProperty("directory_fingerprint",d.fingerprint());r.addProperty("dimension","test:synthetic_route_graph");var hashes=new JsonObject();hashes.addProperty("mesh/tv_facilities_r16.json","a".repeat(64));hashes.addProperty("mesh/air_cradle_r31.json","b".repeat(64));r.add("mesh_sources",hashes);for(String a:List.of("aircraft","airports","nodes","corridors","receivers","missions"))r.add(a,new JsonArray());
        var airport=new JsonObject();airport.addProperty("id","surface");airport.addProperty("region","SURFACE");airport.add("domain",numbers(-1000,-100,-1000,1000,1000,1000));airport.addProperty("takeoff_node","stand0");airport.add("occupancy",ids("air_slot0"));r.getAsJsonArray("airports").add(airport);
        var below=airport.deepCopy();below.addProperty("id","below");below.addProperty("region","GEOFRONT");below.add("domain",numbers(-1000,-2000,-1000,1000,-1100,1000));below.addProperty("takeoff_node","underground");r.getAsJsonArray("airports").add(below);node(r,"underground","GEOFRONT",0,-1500,false,"air_path");node(r,"pickup","SURFACE",500,84,true,"air_path");node(r,"receiver","SURFACE",50,84,true,"space1");node(r,"clear","SURFACE",50,300,false,"air_clear");
        var receiver=new JsonObject();receiver.addProperty("port","port_b1l1");receiver.addProperty("region","SURFACE");receiver.addProperty("flight_node","receiver");receiver.add("stopped_cargo_frame",rigid(50,-28,0));var routes=new JsonObject();d.ports().get("port_b1l1").reverseRoutes().forEach((v,id)->routes.addProperty(v.toString(),id));receiver.add("reverse_routes",routes);r.getAsJsonArray("receivers").add(receiver);
        corridor(r,"loaded","pickup","receiver","","air_path");corridor(r,"retreat","receiver","clear","","air_clear");
        for(int i=0;i<3;i++)
        {
            node(r,"stand"+i,"SURFACE",i*160,84,false,"air_slot"+i);var a=new JsonObject();a.addProperty("id","aircraft"+i);a.addProperty("entity_uuid",new UUID(0,501+i).toString());a.addProperty("expected_type","projectseele:un_transport");a.addProperty("serial",i);a.addProperty("airport","surface");a.addProperty("stand_node","stand"+i);a.add("support_cells",cells(i*160,72,0));r.getAsJsonArray("aircraft").add(a);
            corridor(r,"out"+i,"stand"+i,"pickup","","air_path");corridor(r,"back"+i,"pickup","stand"+i,"out"+i,"air_path");corridor(r,"home"+i,"clear","stand"+i,"","air_slot"+i);var m=new JsonObject();m.addProperty("id","mission"+i);m.addProperty("intent","RECOVER");m.addProperty("aircraft","aircraft"+i);m.add("variants",numbers(0));m.addProperty("pickup_region","SURFACE");m.add("pickup_domain",numbers(400,-100,-100,600,500,100));m.addProperty("pickup_node","pickup");m.addProperty("receiver","port_b1l1");m.add("outbound",ids("out"+i));m.add("loaded",ids("loaded"));m.add("retreat",ids("retreat","home"+i));r.getAsJsonArray("missions").add(m);
        }
        return r;
    }
    public static void main(String[] args)
    {
        var ground=NervRouteCoreR52Test.rootFixtureForNativeBindingTest();for(String id:List.of("air_slot0","air_slot1","air_slot2","air_path","air_clear")){var x=new JsonObject();x.addProperty("id",id);x.addProperty("kind","SPACE");x.addProperty("component","synthetic/"+id);ground.getAsJsonArray("resources").add(x);}var d=NervRouteDirectoryR52.parse(ground);var r=fixture(d);var m=NervAirTransportManifestR52.parse(r,d);
        check(m.aircraft().size()==3&&m.missions().size()==3,"Three explicitly original aircraft share one directory graph");check(!m.installed(),"A design air manifest cannot start native flights");check(m.region(new Vec3(500,-28,0))==NervRouteDirectoryR52.Region.SURFACE,"Negative Y is not a guessed underground classification");check(m.region(new Vec3(0,-1500,0))==NervRouteDirectoryR52.Region.GEOFRONT,"Actual disjoint Root domain determines underground recovery");
        var bad=r.deepCopy();bad.addProperty("directory_fingerprint","0".repeat(64));var mismatch=bad;rejects(()->NervAirTransportManifestR52.parse(mismatch,d),"Air pool cannot split into a second resource system");
        bad=r.deepCopy();bad.getAsJsonArray("aircraft").get(1).getAsJsonObject().addProperty("entity_uuid",new UUID(0,501).toString());var duplicate=bad;rejects(()->NervAirTransportManifestR52.parse(duplicate,d),"Original plane UUIDs cannot duplicate");
        bad=r.deepCopy();bad.getAsJsonArray("aircraft").get(0).getAsJsonObject().addProperty("expected_type","projectseele:ac130");var ac130=bad;rejects(()->NervAirTransportManifestR52.parse(ac130,d),"Protected AC130 cannot be mistaken for the Root NERV fleet");
        bad=r.deepCopy();bad.getAsJsonObject("mesh_sources").remove("mesh/air_cradle_r31.json");var source=bad;rejects(()->NervAirTransportManifestR52.parse(source,d),"Incomplete actual renderer geometry selection rejected");
        bad=r.deepCopy();bad.getAsJsonArray("nodes").get(0).getAsJsonObject().getAsJsonObject("frame").getAsJsonObject("plane").add("quaternion_xyzw",numbers(Math.sqrt(.5),0,0,Math.sqrt(.5)));var tilt=bad;rejects(()->NervAirTransportManifestR52.parse(tilt,d),"Unsupported plane pitch cannot pass while renderer stays yaw-only");
        bad=r.deepCopy();bad.getAsJsonArray("corridors").get(0).getAsJsonObject().add("occupancy",ids("second_air_resource_system"));var alias=bad;rejects(()->NervAirTransportManifestR52.parse(alias,d),"Every physical air SPACE ID belongs to the same ground directory");
        bad=r.deepCopy();bad.getAsJsonArray("missions").get(0).getAsJsonObject().add("loaded",new JsonArray());var gap=bad;rejects(()->NervAirTransportManifestR52.parse(gap,d),"No empty teleport chain accepted");
        bad=r.deepCopy();var delivery=bad.getAsJsonArray("receivers").get(0).getAsJsonObject();delivery.addProperty("delivery",true);delivery.add("reverse_routes",new JsonObject());delivery.add("actual_support_cells",cells(50,-29,0));delivery.add("gates",new JsonArray());for(var raw:bad.getAsJsonArray("missions"))raw.getAsJsonObject().addProperty("intent","DELIVER");check(NervAirTransportManifestR52.parse(bad,d).receiver("port_b1l1").delivery(),"Explicit actual supported delivery is distinct from typed mechanical recovery");bad.getAsJsonArray("missions").get(0).getAsJsonObject().addProperty("intent","FAR_MOUNTAIN");check(NervAirTransportManifestR52.parse(bad,d).missions().get("mission0").intent()==NervAirTransportManifestR52.Intent.FAR_MOUNTAIN,"Explicit far-mountain intent preserves the same original aircraft/data contract");delivery.remove("actual_support_cells");var unsupported=bad;rejects(()->NervAirTransportManifestR52.parse(unsupported,d),"Delivery cannot fabricate a heightmap landing point");
        var query=new net.minecraft.world.phys.AABB(0,0,0,20,10,10);check(NervAirspaceCoverageR52.covered(query,List.of(new net.minecraft.world.phys.AABB(0,0,0,10,10,10),new net.minecraft.world.phys.AABB(10,0,0,20,10,10))),"A full original assembly can continuously cross adjacent declared shared spaces");check(!NervAirspaceCoverageR52.covered(query,List.of(new net.minecraft.world.phys.AABB(0,0,0,10,10,10),new net.minecraft.world.phys.AABB(10.002,0,0,20,10,10))),"Real gaps between resource domains never become traversable by union coverage");
        bad=r.deepCopy();bad.getAsJsonArray("corridors").get(3).getAsJsonObject().addProperty("ticks",11);var clock=bad;rejects(()->NervAirTransportManifestR52.parse(clock,d),"Authored reciprocal corridor cannot silently change the physical cancellation clock");
        bad=r.deepCopy();corridor(bad,"cross_region","underground","pickup","","air_path");var unapproved=bad;rejects(()->NervAirTransportManifestR52.parse(unapproved,d),"No aircraft crosses an undeclared surface/underground shaft");
        var shaft=new JsonObject();shaft.addProperty("id","synthetic_aircraft_shaft");shaft.addProperty("underground_node","underground");shaft.addProperty("surface_node","pickup");shaft.addProperty("motion","AIRCRAFT");shaft.add("occupancy",ids("air_path"));var shafts=new JsonArray();shafts.add(shaft);bad.add("shafts",shafts);check(NervAirTransportManifestR52.parse(bad,d).corridor("cross_region")!=null,"Explicit actual aircraft shaft uses the very same shared physical SPACE");
        shaft.addProperty("motion","GROUND_MECHANICAL");var mechanicalOnly=bad;rejects(()->NervAirTransportManifestR52.parse(mechanicalOnly,d),"Ground mechanical-only shaft cannot be relabelled as an aircraft passage");
        var nonFinite=rigid(Double.NaN,0,0);rejects(()->NervAirTransportManifestR52.rigid(nonFinite),"Unknown nonfinite measured translation never becomes an aircraft frame");
        if(args.length>0)try{java.nio.file.Files.writeString(java.nio.file.Path.of(args[0]),new GsonBuilder().setPrettyPrinting().create().toJson(r));java.nio.file.Files.writeString(java.nio.file.Path.of(args[0]+".ground.json"),new GsonBuilder().setPrettyPrinting().create().toJson(ground));}catch(java.io.IOException failed){throw new IllegalStateException(failed);}
        System.out.println("PASS R52 explicit multi-plane/region/source/shared-space/recovery/delivery manifest: "+checks);
    }
}
